    print(f"Loaded {len(batch)} samples.")
    all_valid = True
    for i, p in enumerate(batch):
        v_ok, v_msg = validate_pair(p)
        c_res, c_msg = clean_sample(p["raw_asr"], p["refined_text"])
        words = len(p["refined_text"].split())
        raw_words = len(p["raw_asr"].split())
        ratio = words / raw_words
        print(f"Sample {i+1}: words={words}, raw={raw_words}, ratio={ratio:.2f}, v_ok={v_ok} ({v_msg}), cleaner={c_msg}")
        if not v_ok or c_msg != "kept":
            all_valid = False

    b_ok, b_msg, counts = validate_batch(batch, min_short=4, min_medium=6, min_long=10)
    print(f"\nBatch validation: {b_ok} ({b_msg})")
    print(f"Tier counts: {counts}")
    print(f"Overall status: {'ALL PASSED' if all_valid and b_ok else 'FAILED'}")
